-- Report ID : RPT_309
-- Report    : Deal Income
-- Module    : Deal
-- Source    : Oracle RMS / MFCS RDS Views
-- Generated : Extracted from DVA file
--------------------------------------------------------------------------------

SELECT     dh.DEAL_ID,     dh.TYPE AS DEAL_TYPE,     dh.STATUS AS DEAL_STATUS,     dh.SUPPLIER,     s.SUP_NAME AS SUPPLIER_NAME,     dh.CURRENCY_CODE,     dh.ACTIVE_DATE,     dh.CLOSE_DATE,     dh.BILLING_TYPE,     dh.BILL_BACK_PERIOD,     dh.DEAL_INCOME_CALCULATION,     dh.REBATE_IND,     dh.REBATE_CALC_TYPE,     dh.ACTUAL_MONIES_EARNED_TO_DATE AS HEADER_MONIES_EARNED,     dh.TURNOVER_TO_DATE AS HEADER_TURNOVER,     dd.DEAL_DETAIL_ID,     dd.DEAL_COMP_TYPE,     dd.COLLECT_START_DATE,     dd.COLLECT_END_DATE,     dd.DEAL_CLASS,     dd.TOTAL_FORECAST_UNITS,     dd.TOTAL_FORECAST_REVENUE,     dd.TOTAL_BUDGET_TURNOVER,     dd.ACTUAL_MONIES_EARNED_TO_DATE AS DETAIL_MONIES_EARNED,     dd.TURNOVER_TO_DATE AS DETAIL_TURNOVER,     af.REPORTING_DATE,     af.ACTUAL_FORECAST_IND,     af.BASELINE_TURNOVER,     af.BUDGET_TURNOVER,     af.BUDGET_INCOME,     af.ACTUAL_FORECAST_TURNOVER,     af.ACTUAL_FORECAST_INCOME,     af.ACTUAL_INCOME,     af.INVC_PROCESSED_IND,     af.ACTUAL_FORECAST_INCOME - af.BUDGET_INCOME AS INCOME_VARIANCE FROM rds_wv_deal_head dh INNER JOIN rds_wv_deal_detail dd ON dd.DEAL_ID = dh.DEAL_ID INNER JOIN rds_wv_sups s ON s.SUPPLIER = dh.SUPPLIER LEFT JOIN rds_wv_deal_actuals_forecast af ON af.DEAL_ID = dd.DEAL_ID AND af.DEAL_DETAIL_ID = dd.DEAL_DETAIL_ID WHERE dh.STATUS NOT IN ('C', 'R')